105	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
106	    @Override
107	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
108	        Collection<Owner> owners;
109	        if (lastName != null) {
110	            owners = this.clinicService.findOwnerByLastName(lastName);
111	        } else {
112	            owners = this.clinicService.findAllOwners();
113	        }
114	        if (owners.isEmpty()) {
115	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
116	        }
117	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
118	    }
